import base64, json, os, traceback
try:
    import notebookutils  # Fabric runtime
except Exception:
    notebookutils = None

# The sealed `_contracts/` registry, embedded byte-for-byte from the approved design. Git
# sync brings notebooks/pipelines as workspace ITEMS but never data files, so this project
# self-populates the contracts it (and every driver/seed) reads — no manual upload, no
# deploy.py. Payload = base64(json({relpath: base64(bytes)})).
_CONTRACTS_PAYLOAD = ""
FILES = "/lakehouse/default/Files"
try:
    # Preflight: this notebook writes into a DEFAULT Lakehouse's Files (the target Lakehouse
    # GUID is per-tenant, so it is intentionally NOT baked into the deployed notebook). Without
    # one attached, `/lakehouse/default` is unmounted and Files/ resolves to per-user scratch —
    # fail fast with an actionable message instead of a cryptic blobfuse/OneLake 400.
    if not os.path.isdir(FILES):
        raise RuntimeError(
            "No default Lakehouse is attached to this notebook. Attach one and re-run: "
            "Explorer (left panel) -> Add data items -> your Lakehouse (e.g. the one this "
            "project targets) -> set as default. 00_setup writes the embedded contracts into "
            "its Files/ll_contracts."
        )
    _manifest = json.loads(base64.b64decode(_CONTRACTS_PAYLOAD).decode('utf-8'))
    _written = 0
    for _rel, _b64 in sorted(_manifest.items()):
        _data = base64.b64decode(_b64)
        _fp = f"{FILES}/ll_contracts/{_rel}"
        try:
            # FUSE write is BYTE-EXACT (writes the raw bytes) — the primary path.
            os.makedirs(os.path.dirname(_fp), exist_ok=True)
            with open(_fp, "wb") as _f:
                _f.write(_data)
        except Exception:
            # OneLake API fallback (contracts are utf-8 YAML, so text is faithful here).
            notebookutils.fs.put(f"Files/ll_contracts/{_rel}", _data.decode('utf-8'), True)
        _written += 1
    print(f"Materialised {_written} contract file(s) into Files/ll_contracts")
except Exception:
    tb = traceback.format_exc()
    print(tb)
    try:
        notebookutils.fs.put("Files/ll_logs/setup_error.txt", tb, True)
    except Exception:
        pass
    raise

