# 00_setup — idempotent bootstrap of the schema-enabled Lakehouse.
# Creates one schema per discovered domain + a shared `quarantine` schema + a
# per-domain run-log Delta table + the OneLake Files landing/log folders. Safe to
# re-run: every statement is IF NOT EXISTS.
import os, traceback
try:
    import notebookutils  # Fabric runtime
except Exception:
    notebookutils = None

FILES = "/lakehouse/default/Files"


def _list_domains():
    """Domain dir names under Files/ll_contracts (notebookutils first, FUSE fallback)."""
    try:
        names = [f.name.rstrip("/") for f in notebookutils.fs.ls("Files/ll_contracts")
                 if getattr(f, 'isDir', False)]
        if names:
            return sorted(names)
    except Exception:
        pass
    try:
        base = f"{FILES}/ll_contracts"
        return sorted(d for d in os.listdir(base) if os.path.isdir(os.path.join(base, d)))
    except Exception:
        return []


def _sql(stmt):
    print(f"  -> {stmt}")
    spark.sql(stmt)  # noqa: F821 (Fabric global)


_RUN_LOG_COLS = (
    "(pipeline_run_id STRING, run_id STRING, timestamp STRING, engine STRING, "
    "contract STRING, contract_version STRING, stage STRING, dataset STRING, "
    "domain STRING, system STRING, environment STRING, data_layer STRING, "
    "status STRING, error_message STRING, counts_source BIGINT, counts_total BIGINT, "
    "counts_good BIGINT, counts_quarantined BIGINT, quarantine_ratio DOUBLE)"
)

try:
    domains = _list_domains()
    print(f"Domains discovered: {domains}")
    if not domains:
        raise RuntimeError(
            "No domains under Files/ll_contracts — the embedded contracts did not "
            "materialise (see the cell above) and the schema-enabled lakehouse must be "
            "attached as this notebook's default. Re-run 00_setup."
        )
    _sql("CREATE SCHEMA IF NOT EXISTS quarantine")
    for domain in domains:
        _sql(f"CREATE SCHEMA IF NOT EXISTS `{domain}`")
        _sql(f"CREATE TABLE IF NOT EXISTS `{domain}`._pipeline_run_log {_RUN_LOG_COLS} USING DELTA")
    for sub in ["ll_logs"] + [f"landing_{d}" for d in domains]:
        try:
            notebookutils.fs.mkdirs(f"Files/{sub}")
        except Exception:
            os.makedirs(f"{FILES}/{sub}", exist_ok=True)
        print(f"  ok Files/{sub}")
    print("=" * 60)
    print(f"  Provisioned schemas: quarantine, {', '.join(domains)}")
    print("=" * 60)
except Exception:
    tb = traceback.format_exc()
    print(tb)
    try:
        notebookutils.fs.put("Files/ll_logs/setup_error.txt", tb, True)
    except Exception:
        pass
    raise

